SELECT sku, product_name, pack_size, flow_type, selling_price_inr, cost_price_inr, units_per_case, case_weight_kg, dc_slot 
FROM store.products 
WHERE product_name ILIKE '%atta%' OR pack_size ILIKE '%5 kg%';

SELECT column_name, data_type 
FROM information_schema.columns 
WHERE table_schema = 'store' AND table_name = 'products';

